export const getRecommendations = async (userPreferences, watchlist) => {
  const genres = watchlist.map(m => m.genre_ids).flat();
  const response = await api.get('/discover/movie', {
    params: {
      with_genres: [...new Set(genres)].join(','),
      sort_by: 'popularity.desc',
      vote_count_gte: 100
    }
  });
  return response.data.results;
};

import axios from 'axios';

interface AIResponse {
  data: string;
  id: string;
}

export const generateAIResponse = async (promptText: string): Promise<AIResponse> => {
  try {
    const response = await axios.post<AIResponse>('/api/generate-text', { prompt: promptText });
    return response.data;
  } catch (error) {
    console.error('Error calling AI service:', error);
    throw new Error('Failed to generate AI response.');
  }
};
